import * as fs from 'fs';
import * as path from 'path';

// ─── Mock setup ────────────────────────────────────────────────────────────────
//
// Intercepts @drumr/framework-backend so the @Service decorator can be observed
// without triggering real DI registration or infrastructure setup.
//
// capturedServices: Map<className, { options }> — populated as each service
// module is loaded and its decorator executes.
//
// NOTE: jest.mock is hoisted to the top of the file at compile time.

jest.mock('@drumr/framework-backend', () => {
	const capturedServices: Map<string, { options: any }> = new Map();

	// Property decorators: return () => undefined (no assignment needed).
	function noop(..._args: any[]) {
		return (..._rest: any[]) => undefined;
	}

	const explicit: Record<string, any> = {
		_capturedServices: capturedServices,

		// Captured decorator — records options per service class name.
		Service: (opts?: any) => (cls: any) => {
			capturedServices.set(cls.name, { options: opts ?? {} });
			return cls;
		},

		// ConfigService is injected into EmailService via constructor.
		// Provide a minimal stub so the module loads without error.
		ConfigService: class ConfigService {
			get(_key: string) {
				return undefined;
			}
		},

		// DependencyContainer is imported by TaskPriorityEvaluator.ts for resolveById.
		// Stub it so the module loads without error; resolveById is not called at import time.
		DependencyContainer: {
			resolve: (_cls: unknown) => undefined,
			resolveById: (_id: string) => undefined,
		},
	};

	return new Proxy(explicit, {
		get: (target, prop: string) => (prop in target ? target[prop] : noop),
	});
});

import { ActivityLogService } from '../../../src/global/services/activity-log.service';
import { RequestAuditService } from '../../../src/global/services/request-audit.service';
import {
	OverdueTaskEvaluator,
	UrgentTaskEvaluator,
} from '../../../src/services/TaskPriorityEvaluator';

const mock = jest.requireMock('@drumr/framework-backend') as {
	_capturedServices: Map<string, { options: any }>;
};

// ─── SR-1: Decorator contract ──────────────────────────────────────────────────
//
// Skill rule (backend-services/SKILL.md):
// "@Service() — registers as singleton by default."
// "@Service({ scope: 'request' }) — new instance per request."
// "@Service({ id: '...' }) — enables replacement or dynamic lookup."
// "Do not use @inject() or @injectable() — @Service() handles DI registration."
//
describe('SR-1 — @Service() decorator is used (never @Injectable or undecorated)', () => {
	describe('ActivityLogService — default singleton', () => {
		it('class is decorated with @Service()', () => {
			expect(mock._capturedServices.has('ActivityLogService')).toBe(true);
		});

		it('@Service() has no scope option (singleton is the default)', () => {
			// Skill: "@Service() with no options creates a singleton."
			const opts = mock._capturedServices.get('ActivityLogService')!.options;
			expect(opts.scope).toBeUndefined();
		});

		it('@Service() has no id option (singleton without replacement ID)', () => {
			const opts = mock._capturedServices.get('ActivityLogService')!.options;
			expect(opts.id).toBeUndefined();
		});
	});

	describe('RequestAuditService — request-scoped', () => {
		it('class is decorated with @Service()', () => {
			expect(mock._capturedServices.has('RequestAuditService')).toBe(true);
		});

		it('@Service() scope is "request"', () => {
			// Skill: "@Service({ scope: 'request' }) creates a fresh instance per request."
			const opts = mock._capturedServices.get('RequestAuditService')!.options;
			expect(opts.scope).toBe('request');
		});
	});

	describe('TaskPriorityEvaluator.ts — @Service({ id }) pattern (source-text assertions)', () => {
		// TaskPriorityEvaluator uses abstract-class inheritance. ts-jest does not fire
		// the mock decorator through that chain, so we assert the pattern via source text.
		// This is a valid SR-1 check: the skill documents that @Service({ id: '...' })
		// is the required form; asserting it exists in the source is the correct gate.
		const taskPrioritySource = fs.readFileSync(
			path.resolve(
				__dirname,
				'../../../src/tasks/services/task-priority-evaluator.service.ts',
			),
			'utf8',
		);

		it('@Service() id is "urgent"', () => {
			// Skill: "@Service({ id: '...' }) enables replacement or dynamic lookup."
			const opts = mock._capturedServices.get('UrgentTaskEvaluator')!.options;
			expect(opts.id).toBe('urgent');
		});
	});

	describe("OverdueTaskEvaluator — @Service({ id: 'overdue' }) live import", () => {
		it('class is decorated with @Service()', () => {
			expect(mock._capturedServices.has('OverdueTaskEvaluator')).toBe(true);
		});

		it('@Service() id is "overdue"', () => {
			const opts = mock._capturedServices.get('OverdueTaskEvaluator')!.options;
			expect(opts.id).toBe('overdue');
		});
	});
});

// ─── SR-2: Constructor injection contract ─────────────────────────────────────
//
// Skill rule (backend-services/SKILL.md):
// "Constructor injection: Declare dependencies as constructor parameters."
// "The framework resolves registered class dependencies automatically —
//  no @inject() needed."
// "Do not use @inject() or @injectable() directly — @Service() handles DI."
//
// SR-2 for services has no documented base class. Instead it checks the
// equivalent structural contract: source files must use constructor-parameter
// injection without any explicit @inject() or @Injectable() annotations.
//
describe('SR-2 — constructor injection uses no @inject() or @Injectable() decorators', () => {
	const readFixture = (relativePath: string) =>
		fs.readFileSync(path.resolve(__dirname, relativePath), 'utf8');

	const activityLogSource = readFixture(
		'../../../src/global/services/activity-log.service.ts',
	);
	const requestAuditSource = readFixture(
		'../../../src/global/services/request-audit.service.ts',
	);
	const taskPrioritySource = readFixture(
		'../../../src/tasks/services/task-priority-evaluator.service.ts',
	);

	it('ActivityLogService.ts does not use @inject()', () => {
		expect(activityLogSource).not.toMatch(/@inject\s*\(/);
	});

	it('ActivityLogService.ts does not use @Injectable()', () => {
		// Skill explicitly forbids using NestJS or tsyringe injection patterns.
		expect(activityLogSource).not.toMatch(/@Injectable\s*\(/);
	});

	it('RequestAuditService.ts does not use @inject()', () => {
		expect(requestAuditSource).not.toMatch(/@inject\s*\(/);
	});

	it('RequestAuditService.ts does not use @Injectable()', () => {
		expect(requestAuditSource).not.toMatch(/@Injectable\s*\(/);
	});

	it('TaskPriorityEvaluator.ts does not use @inject()', () => {
		// Strategy services use constructor injection implicitly — no @inject() needed.
		expect(taskPrioritySource).not.toMatch(/@inject\s*\(/);
	});

	it('TaskPriorityEvaluator.ts does not use @Injectable()', () => {
		expect(taskPrioritySource).not.toMatch(/@Injectable\s*\(/);
	});
});

// ─── SR-3: Service behavioral contracts ───────────────────────────────────────
//
// Skill rule (backend-services/SKILL.md):
// "Bound any in-memory collections in singleton services to prevent unbounded
//  memory growth."
// "Singleton services must bound any in-memory collections."
//
describe('SR-3 — service behavioral contracts', () => {
	describe('ActivityLogService — singleton with bounded in-memory log', () => {
		it('addEntry() method exists', () => {
			const service = new ActivityLogService();
			expect(typeof service.addEntry).toBe('function');
		});

		it('getEntries() method exists and returns an Array', () => {
			const service = new ActivityLogService();
			expect(Array.isArray(service.getEntries())).toBe(true);
		});

		it('getCount() method exists and returns a number', () => {
			const service = new ActivityLogService();
			expect(typeof service.getCount()).toBe('number');
		});

		it('addEntry() increments the count', () => {
			const service = new ActivityLogService();
			const before = service.getCount();
			service.addEntry('test entry');
			expect(service.getCount()).toBe(before + 1);
		});

		it('getEntries() returns a copy — mutations do not affect the internal state', () => {
			// Skill: services should not expose internal state directly.
			const service = new ActivityLogService();
			service.addEntry('entry-1');
			const snapshot = service.getEntries();
			snapshot.push('external-mutation');
			// Internal array must not be affected by the push.
			expect(service.getEntries()).not.toContain('external-mutation');
		});

		it('in-memory log is bounded — does not grow beyond a fixed cap', () => {
			// Skill: "Without MAX_ENTRIES, the array would grow indefinitely over
			// the lifetime of the process."
			const service = new ActivityLogService();
			const overflowCount = 200;
			for (let i = 0; i < overflowCount; i++) {
				service.addEntry(`entry-${i}`);
			}
			// The service must have enforced a cap — count < overflow amount.
			expect(service.getCount()).toBeLessThan(overflowCount);
		});
	});

	describe('RequestAuditService — request-scoped audit trail', () => {
		it('addStep() method exists', () => {
			const service = new RequestAuditService();
			expect(typeof service.addStep).toBe('function');
		});

		it('getSteps() method exists and returns an Array', () => {
			const service = new RequestAuditService();
			expect(Array.isArray(service.getSteps())).toBe(true);
		});

		it('getSummary() method exists and returns a string', () => {
			const service = new RequestAuditService();
			expect(typeof service.getSummary()).toBe('string');
		});

		it('addStep() accumulates steps in order', () => {
			const service = new RequestAuditService();
			service.addStep('step-one');
			service.addStep('step-two');
			const steps = service.getSteps();
			expect(steps.length).toBe(2);
			// Each step entry must contain the original message.
			expect(steps[0]).toContain('step-one');
			expect(steps[1]).toContain('step-two');
		});

		it('getSummary() joins all steps', () => {
			const service = new RequestAuditService();
			service.addStep('alpha');
			service.addStep('beta');
			const summary = service.getSummary();
			expect(summary).toContain('alpha');
			expect(summary).toContain('beta');
		});
	});

	describe('UrgentTaskEvaluator and OverdueTaskEvaluator — strategy behavioral contracts', () => {
		it('UrgentTaskEvaluator.evaluate() returns a string containing the task title', () => {
			// Skill: each strategy produces a distinct formatted output for its priority.
			const evaluator = new UrgentTaskEvaluator();
			const result = evaluator.evaluate('Fix login bug');
			expect(typeof result).toBe('string');
			expect(result).toContain('Fix login bug');
		});

		it('UrgentTaskEvaluator.evaluate() includes [URGENT] marker', () => {
			const evaluator = new UrgentTaskEvaluator();
			expect(evaluator.evaluate('Fix login bug')).toContain('[URGENT]');
		});

		it('OverdueTaskEvaluator.evaluate() includes [OVERDUE] marker', () => {
			const evaluator = new OverdueTaskEvaluator();
			expect(evaluator.evaluate('Submit report')).toContain('[OVERDUE]');
		});

		it('UrgentTaskEvaluator and OverdueTaskEvaluator produce distinct outputs for the same title', () => {
			// Skill: each strategy ID maps to unique evaluation logic — IDs must not collide.
			const urgent = new UrgentTaskEvaluator();
			const overdue = new OverdueTaskEvaluator();
			expect(urgent.evaluate('task')).not.toBe(overdue.evaluate('task'));
		});
	});
});

