// ─── SR-4 adversarial: repo-wide scan — all src/services/**/*.ts ──────────────
//
// Skill rules (backend-services/SKILL.md § Don't):
// "Do not import from 'tsyringe' directly — use exports from @drumr/framework-backend."
// "Do not use @inject() or @injectable() directly."
// "Do not generate generic Express middleware, NestJS providers, or Spring @Service patterns."
//
// A repo-wide scan raises R from 1 to 2 by covering every service file,
// not just the three primary fixtures.
//
describe('SR-4 adversarial — repo-wide scan: all src/services/**/*.ts', () => {
	function collectServiceSources(
		dir: string,
	): Array<{ file: string; source: string }> {
		const results: Array<{ file: string; source: string }> = [];
		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
			const fullPath = path.join(dir, entry.name);
			if (entry.isDirectory()) {
				results.push(...collectServiceSources(fullPath));
			} else if (entry.name.endsWith('.ts') && !entry.name.endsWith('.d.ts')) {
				results.push({
					file: fullPath,
					source: fs.readFileSync(fullPath, 'utf8'),
				});
			}
		}
		return results;
	}

	const servicesDir = path.resolve(__dirname, '../../../src/services');
	const allServiceSources = collectServiceSources(servicesDir);

	it('no service file imports from "tsyringe" directly', () => {
		// Skill: "Do not import from tsyringe — use @drumr/framework-backend exports."
		const violations = allServiceSources.filter((f) =>
			/(from\s+['"]tsyringe['"]|require\(\s*['"]tsyringe['"]\s*\)|import\(\s*['"]tsyringe['"]\s*\))/.test(
				f.source,
			),
		);
		expect(violations.map((f) => f.file)).toHaveLength(0);
	});

	it('no service file uses @injectable() / @Injectable() decorator', () => {
		// Skill: "Do not use @inject() or @injectable() directly." (@Injectable is also forbidden)
		const violations = allServiceSources.filter((f) =>
			/@(injectable|Injectable)\s*\(/.test(f.source),
		);
		expect(violations.map((f) => f.file)).toHaveLength(0);
	});

	it('no service file uses @inject() decorator', () => {
		// Skill: "Do not use @inject() or @injectable() directly."
		const violations = allServiceSources.filter((f) =>
			/@inject\s*\(/.test(f.source),
		);
		expect(violations.map((f) => f.file)).toHaveLength(0);
	});
});
